INSERT INTO keyValue (keyColumn, valueColumn)
VALUES ('TERMS_CONTENT', '[{"title":"1. Introduction","iconBg":"#fee2e2","content":["These Terms and Conditions (\\"Terms\\") govern your use of the Vaibhav Vivaaha Matrimony platform, website and mobile application (together, the \\"Service\\"), operated by «LEGAL ENTITY NAME» (\\"we\\", \\"us\\", \\"our\\").","By creating an account or using the Service you agree to these Terms. If you do not agree, please do not use the Service.","The Service is a matrimonial introduction platform. We provide a venue for members to discover and contact each other. We are not a marriage broker, and we do not arrange, solemnise or guarantee any marriage."]},{"title":"2. Eligibility and Accounts","iconBg":"#dbeafe","content":["2.1 Age: You must be of legal marriageable age under Indian law to register — 21 years for men and 18 years for women (Prohibition of Child Marriage Act, 2006). We may request proof of age.","2.2 Marital status: You must be legally free to marry. Registering while married, or without a decree of divorce having been granted, is prohibited.","2.3 Accuracy: You agree to provide accurate, current and complete information and to keep it updated. Profiles found to contain false information may be suspended without refund.","2.4 Account security: You are responsible for your PIN and for activity on your account.","2.5 Family Access: Members on eligible plans may create an additional Family Access login for a parent or guardian. You remain fully responsible for everything done through that login, and you may revoke it at any time from Settings.","2.6 One profile per person: You may maintain only one profile. Duplicate profiles may be removed."]},{"title":"3. User Conduct","iconBg":"#d1fae5","content":["You agree not to:","• Provide false, misleading or impersonated information","• Harass, abuse, threaten or stalk other members","• Post obscene, defamatory, or unlawful content","• Solicit money, donations, investments or engage in commercial activity","• Use the Service to promote any other service or collect member data","• Use automated systems, scrapers or bots to access the Service","• Attempt to gain unauthorised access to any account or system","We may remove content, suspend or terminate accounts, and report unlawful activity to the authorities."]},{"title":"4. Privacy and Your Data","iconBg":"#ede9fe","content":["4.1 What we collect: registration details, profile information, photographs, horoscope details (including date, time and place of birth), and usage data. Our Privacy Policy explains this in full.","4.2 Profile visibility: your profile is visible to other members. You control certain fields through Privacy Settings, and photographs, horoscope and mobile number can be restricted so that other members must request access.","4.3 Sharing contact details: your mobile number and email are disclosed to another member only where you have accepted their interest, or where you have approved their specific request. Paid plans include a limited number of contact reveals.","4.4 Purpose: we process your data to operate the matchmaking service and for safety and fraud prevention. We do not sell or rent your personal data.","4.5 Your rights: under the Digital Personal Data Protection Act, 2023 you may access, correct, or request erasure of your personal data, and withdraw consent, by contacting our Grievance Officer (Section 10).","4.6 Retention: see Section 8."]},{"title":"5. Paid Plans and Payments","iconBg":"#fef3c7","content":["5.1 Paid plans provide additional features as described in the app at the time of purchase.","5.2 Plans are one-time purchases for a fixed duration. They do NOT auto-renew, and you will not be charged again unless you purchase another plan.","5.3 Payments may be completed in-app or, where offered, through a Relationship Manager. Payments made by upload of proof are activated only after verification by our team.","5.4 Refunds: fees are non-refundable once a plan is activated, except where required by law, or where a payment was charged in error or a plan was not activated. Refund requests must be raised with the Grievance Officer within 7 days of payment.","5.5 We may change plan pricing prospectively. Changes do not affect a plan you have already purchased.","5.6 Suspension or termination for breach of these Terms does not entitle you to a refund."]},{"title":"6. Intellectual Property","iconBg":"#e0e7ff","content":["6.1 The Service, its design, features and content are owned by us and protected by applicable law.","6.2 You retain ownership of the content you upload. You grant us a limited, non-exclusive licence to host, display and distribute it within the Service for the purpose of operating the matchmaking service.","6.3 You may not reproduce, distribute, scrape or create derivative works from the Service or from other members\' profiles."]},{"title":"7. Verification, Disclaimers and Liability","iconBg":"#fee2e2","content":["7.1 Limited verification: where a profile displays a verification badge, it means we have reviewed a document submitted for that specific item (such as identity, education or income). It is a limited, document-based check only. We do NOT conduct background, criminal, financial or medical checks, and a badge is not a guarantee of a member\'s character, intentions or the truth of anything else in their profile.","7.2 Independent enquiry: you are expected to make your own enquiries and verify a member\'s details independently before making any personal or financial commitment. Never send money to another member.","7.3 No guarantee of outcome: we do not guarantee that you will receive responses, find a match, or marry.","7.4 Availability: the Service is provided on an \\"as is\\" and \\"as available\\" basis. We do not guarantee uninterrupted or error-free operation.","7.5 Conduct of members: we are not responsible for the conduct of any member, online or offline. Interactions between members are at your own risk.","7.6 Limitation: to the extent permitted by law, our total liability arising out of or relating to the Service is limited to the amount you paid us in the twelve months preceding the claim. We are not liable for indirect, incidental or consequential loss."]},{"title":"8. Termination and Data Retention","iconBg":"#f3f4f6","content":["8.1 By you: you may delete your account at any time from Settings. Deletion is permanent and removes your profile, photographs, messages, interests and subscription records.","8.2 By us: we may suspend or terminate your account for breach of these Terms, suspected fraud, or unlawful conduct.","8.3 Hiding a chat: removing a conversation from your chat list hides it from your view only. The other member keeps their copy, and message records are retained so that we can investigate reports of abuse. Hiding a chat is not deletion of the messages.","8.4 Retention after deletion: we may retain limited records where required by law, or where necessary to resolve disputes, prevent fraud, or respond to a complaint or lawful request."]},{"title":"9. Changes to these Terms","iconBg":"#ffedd5","content":["We may update these Terms from time to time. Material changes will be notified in the app or by email. Continued use of the Service after a change takes effect constitutes acceptance of the revised Terms."]},{"title":"10. Grievance Redressal","iconBg":"#dbeafe","content":["In accordance with the Information Technology (Intermediary Guidelines and Digital Media Ethics Code) Rules, 2021 and the Digital Personal Data Protection Act, 2023, our Grievance Officer may be contacted at:","Name: «GRIEVANCE OFFICER NAME»","Email: grievance@vaibhavvivaahamatrimony.com","Phone: +91 79045 47565","Address: «REGISTERED OFFICE ADDRESS»","We will acknowledge a complaint within 24 hours and endeavour to resolve it within 15 days of receipt.","To report a member or content within the app, use the Report option on their profile or in the chat."]},{"title":"11. Governing Law and Jurisdiction","iconBg":"#ccfbf1","content":["These Terms are governed by the laws of India. The courts at «CITY», Tamil Nadu shall have exclusive jurisdiction over any dispute arising out of or relating to these Terms or the Service."]},{"title":"12. Contact Us","iconBg":"#e0e7ff","content":["Questions about these Terms:","Email: support@vaibhavvivaahamatrimony.com","Phone: +91 79045 47565","Support hours: Monday to Saturday, 10 AM to 8 PM"]}]');

